INSERT INTO hobby_server_user_roles (username, website, role)
  SELECT username, 'hxh', 'guest' FROM hobby_server_user_roles WHERE website = 'hxh' AND role = 'player'
ON CONFLICT DO NOTHING;
DELETE FROM hobby_server_user_roles WHERE website = 'hxh' AND role = 'player';
DELETE FROM hobby_server_website_roles WHERE website = 'hxh' AND role = 'player';
